insert into public.musa_settings (key, value) values
('funnel_copy', '{"version":"cambios7-2026-06-12","etapas":[{"id":"S00_LLEGADA","objetivo":"Registrar el lead, capturar metadatos (nombre de perfil de WhatsApp, ad_id/referral del anuncio CTWA, timestamp para la ventana del bono de acción rápida) y disparar el saludo en menos de 60 segundos.","disparador":"Primer mensaje entrante de un número sin estado previo (el prellenado del anuncio NO es ''hola''; su contenido se ignora para clasificar, solo se guarda).","mensajes":[],"notas":"Sin mensaje propio: estado interno. Acciones: crear lead, guardar profile_name crudo, evaluar usabilidad del nombre, flags avatar_enviado=false, bono_rapido_hasta=now+24h. CAMBIO 6: cualquier primer mensaje (texto o vacío) dispara la bienvenida. Transición inmediata a S01_SALUDO y de ahí, tras el momento avatar, DIRECTO a S04_GATE18 (sin etapa de país)."},{"id":"S01_SALUDO","objetivo":"Abrir con calidez, presentar a Musa, plantar la promesa del producto y generar expectativa.","disparador":"Transición automática desde S00_LLEGADA.","mensajes":["¡Hola! 😄 Qué bueno tenerte por aquí. Soy *Musa*, asesora de *Modelos IA* 💜","Aquí vas a descubrir cómo crear modelos virtuales hiperrealistas con inteligencia artificial y monetizarlas en internet 💻✨","Pero antes de contarte los detalles… déjame mostrarte algo que te va a encantar 👀 Dame unos segunditos ⏳"],"notas":"Los mensajes salen con efecto tecleo. Transición automática a S02_AVATAR sin esperar respuesta."},{"id":"S02_AVATAR","objetivo":"MOMENTO AVATAR (solo UNA vez por lead, flag avatar_enviado): demostrar el producto en vivo con el video del avatar saludando por nombre y conectarlo con ''esto lo vas a saber crear tú''.","disparador":"Transición automática desde S01_SALUDO. Rama A: nombre usable y hay video. Rama C: hay nombre pero no hay video para ese nombre → genérico.","ramas":{"A":{"condicion":"Nombre de perfil usable y existe video pre-renderizado para ese nombre.","mensajes":["[VIDEO_AVATAR]","¿Viste eso, {{nombre}}? 😏 Esa chica NO existe. Es un modelo creado 100% con inteligencia artificial… y te saludó por tu nombre. Eso exactamente es lo que vas a aprender a crear tú, paso a paso, aunque hoy no sepas nada de IA."],"sin_video":"Te tengo una sorpresa preparada para más adelante 😉 Pero primero lo importante:"},"B":{"condicion":"Nombre de perfil no usable: pedir el nombre antes de mostrar el video.","mensajes":["Por cierto, ¿cómo te llamas? 😊 Quiero mostrarte algo especial y me gustaría hacerlo bien.","[AL RECIBIR EL NOMBRE, SI HAY VIDEO] ¡Listo, {{nombre}}! Mira esto 👇 [VIDEO_AVATAR]","[TRAS EL VIDEO] Esa chica NO existe 🤯 Está creada 100% con inteligencia artificial: su cara, su voz, sus gestos… todo. Y eso exactamente es lo que vas a aprender a crear tú, paso a paso, aunque hoy estés empezando de cero."],"sin_video":"Te tengo una sorpresa preparada para más adelante 😉 Pero primero lo importante:"},"C":{"condicion":"Hay nombre pero no existe video pre-renderizado para ese nombre: usar video genérico.","mensajes":["Mira esto 👇 [VIDEO_AVATAR_GENERICO]","[TRAS EL VIDEO] Esa chica NO existe 🤯 Está creada 100% con inteligencia artificial: su cara, su voz, sus gestos… todo. Y eso exactamente es lo que vas a aprender a crear tú, paso a paso, aunque hoy estés empezando de cero."],"sin_video":"Te tengo una sorpresa preparada para más adelante 😉 Pero primero lo importante:"}},"notas":"Regla dura: una sola vez por lead. CAMBIO 1: tras el momento avatar (o el puente sin_video) se pasa DIRECTO a S04_GATE18; ya NO hay etapa de país."},{"id":"S04_STACK_18","objetivo":"Stack de valor compacto (13 módulos + 4 bonos + bono Plan de Acción 7 Días) y confirmación de mayoría de edad DESPUÉS del stack y ANTES de cualquier detalle del material para adultos.","disparador":"Transición automática desde S02_AVATAR (tras el momento avatar).","mensajes":["Mira TODO lo que incluye *Modelos IA* 👇\n\n🤖 *13 módulos paso a paso:*\n• Cómo funciona el mercado de modelos IA 📊\n• Crear tu modelo hiperrealista desde cero\n• Generar contenido ilimitado con su rostro y estilo\n• Prompts avanzados de imagen y video\n• Automatizar respuestas y atención (como esta 😉)\n• Monetizar packs, suscripciones y contenido exclusivo\n• Atraer tráfico desde TikTok e Instagram\n\n🎁 *Y además 4 bonos:*\n1️⃣ Colección de +20 modelos IA premium\n2️⃣ Audios FemPro\n3️⃣ YouTube Money Machine\n4️⃣ MegaPack Master IA\n\n🎯 Y el bono *Plan de Acción 7 Días* si decides hoy: tu paso a paso para arrancar esta misma semana.\n\nTodo con *acceso de por vida* y soporte por este mismo chat 💜","Eso sí, importante ⚠️: parte del material es exclusivo para mayores de edad. ¿Me confirmas que ya tienes 18 años o más?","[SI RESPONDE QUE ES MENOR] Te agradezco un montón la sinceridad 🙏 Este programa incluye material exclusivo para mayores de edad, así que solo puedo venderlo a partir de los 18. Cuando los cumplas, aquí estaré. ¡Cuídate mucho! 💜"],"notas":"CAMBIO 2: la confirmación se infiere con IA (heurística + clasificador), no exige la palabra ''sí''. Solo ''es_mayor'' → mayor_18=true → S05_PRECIO. ''es_menor'' → S92_MENOR (bloqueo total). ''ambiguo'' → re-preguntar con calidez, sin avanzar. CAMBIO 3: SIN grupo/comunidad en el stack. El bono Plan de Acción 7 Días SÍ se nombra como parte del valor."},{"id":"S05_PRECIO","objetivo":"Revelar el precio único de 9 USD con AMBAS referencias de moneda juntas (sin filtro de país).","disparador":"Confirmación 18+ recibida en S04_STACK_18.","mensajes":["¿Y sabes qué es lo mejor? TODO va junto en un único pago de *9 USD* (equivalente a *{{precio_bs}} Bs* o *{{precio_cop}} COP* a la tasa de hoy) 💥\n\n✅ 13 módulos completos\n✅ Los 4 bonos\n✅ Bono Plan de Acción 7 Días (por decisión rápida)\n✅ Acceso de por vida, sin mensualidades","Y apenas confirme tu pago, te entrego TODO por aquí mismo: enlaces directos de Google Drive, sin esperas ni trámites 🚀"],"notas":"CAMBIO 1: el precio muestra SIEMPRE las dos referencias juntas (Bs y COP), sin preguntar país. CAMBIO 3: sin grupo/comunidad. La tasa en Bs se actualiza a diario vía cron. Transición automática a S06_CIERRE."},{"id":"S06_CIERRE","objetivo":"Pedir la venta de forma directa y sin presión falsa: una pregunta de cierre clara.","disparador":"Transición automática desde S05_PRECIO.","mensajes":["¿Te animas a empezar hoy, {{nombre}}? 😊 ¿Te paso los datos de pago?"],"notas":"SÍ/dale/ok → S07_DATOS_PAGO. Objeción → matriz de objeciones y re-cierre suave. Pregunta fuera de guion → fallback GPT. NUNCA repetir la pregunta de cierre más de 2 veces seguidas sin aportar algo nuevo."},{"id":"S07_DATOS_PAGO","objetivo":"Entregar TODOS los métodos de pago juntos (Venezuela + Colombia), el monto exacto y la instrucción de enviar la captura.","disparador":"Aceptación del cierre (''sí'', ''dale'', ''cómo pago'', ''pásame los datos'') en cualquier etapa posterior al precio.","mensajes":["¡De una, {{nombre}}! 🙌 Tu acceso es de *9 USD* (*{{precio_bs}} Bs* o *{{precio_cop}} COP* a la tasa de hoy). Puedes pagar por el medio que más te sirva 👇","Cuando hagas el pago, envíame la *captura del comprobante* por aquí 📸 y lo verifico enseguida."],"notas":"CAMBIO 1: se muestran TODOS los métodos juntos (bloque Venezuela: Pago Móvil + transferencia BDV; bloque Colombia: Nequi, Bancolombia, llave Bre-B). El motor inserta los bloques de cuentas VÁLIDAS entre mensajes[0] (encabezado) y mensajes[1] (cierre). Solo se envían cuentas no-placeholder; si ninguna es válida, se escala a humano. El bot JAMÁS pide tarjeta, claves ni OTP: solo la captura. Transición a S08_ESPERA_CAPTURA."},{"id":"S08_ESPERA_CAPTURA","objetivo":"Sostener al lead durante el pago, resolver dudas operativas de la transferencia y recibir la imagen del comprobante.","disparador":"Entrada automática tras S07_DATOS_PAGO. Sub-disparador de recordatorio: 15 minutos sin imagen recibida.","mensajes":["[RECORDATORIO 15 MIN] ¿Cómo vas con el pago, {{nombre}}? 😊 Si te surgió algún detalle con la transferencia (banco caído, datos, monto), dime y lo resolvemos juntos.","[SI ENVÍA TEXTO EN VEZ DE IMAGEN, ej. ''ya pagué''] ¡Buenísimo! 🙌 Envíame la captura del comprobante por aquí mismo para verificarlo y entregarte todo de una vez 📸"],"notas":"Imagen recibida → S09_VERIFICACION. Texto/duda → GPT con contexto de pagos y re-pedir la captura."},{"id":"S09_VERIFICACION","objetivo":"Acusar recibo de la captura al instante, fijar expectativa REAL de tiempo y validar el pago antes de entregar.","disparador":"Mensaje entrante con imagen estando en S08_ESPERA_CAPTURA (o en cualquier estado posterior al precio).","mensajes":["¡Recibido, {{nombre}}! 🙌 Dame unos minutos mientras verifico tu pago ✅ Normalmente tarda menos de 15 minutos (en horario de 8am a 10pm).","[FUERA DE HORARIO] ¡Recibido, {{nombre}}! 🙌 Tu comprobante quedó en cola. Nuestro horario de verificación es de 8am a 10pm, así que apenas abramos mañana lo confirmo y te entrego TODO de inmediato. Tu acceso está asegurado, tranqui 💜","[COMPROBANTE ILEGIBLE O NO CUADRA] Mmm, no logro validar este comprobante 🤔 ¿Me confirmas el *número de referencia*, el *banco desde el que pagaste* y la *hora* de la operación? Con eso lo reviso de nuevo.","[PAGO INCOMPLETO] {{nombre}}, veo que el monto no coincide con el total (*{{precio_bs}} Bs* / *{{precio_cop}} COP*). ¿Me ayudas completando la diferencia y me envías esa captura? Apenas cuadre, te entrego todo 🙌"],"notas":"La captura se sube a Storage, un humano (u OCR) la valida. Aprobado → S10_ENTREGA. Prometer SOLO tiempos que se cumplen."},{"id":"S10_ENTREGA","objetivo":"Confirmar el pago, entregar los 17 enlaces ordenados en 2 bloques (sin parecer spam) y dejar al alumno con un primer paso concreto.","disparador":"Verificación aprobada en S09_VERIFICACION.","mensajes":["✅ ¡Pago confirmado! Bienvenido oficialmente a *Modelos IA*, {{nombre}} 🎉 Diste un gran paso.","Te entrego todo organizado en *2 bloques* para que no se te pierda nada. Tip: fija este chat o guarda los enlaces en tus mensajes destacados 📌","📚 *BLOQUE 1 — Curso completo (13 módulos):*\n[ENTREGA_LINKS:modulos_1_13]","🎁 *BLOQUE 2 — Tus 4 bonos:*\n[ENTREGA_LINKS:bonos_1_4]\n\n(Recuerda: el material 🔞 es de uso personal y solo para adultos)","Mi consejo para arrancar 💪: con dedicación y aplicando el paso a paso, empieza HOY por el *Módulo 1* (te toma ~20 minutos) y en poco tiempo verás tu primer modelo creado y publicado. Cualquier duda, me escribes por aquí. ¡Nos vemos adentro! — Musa 💜 | Modelos IA"],"notas":"CAMBIO 3: SIN bloque de comunidad/grupo. Los enlaces se agrupan en 2 mensajes (módulos / bonos), nunca 17 separados. Verificar mayor_18=true antes del Bloque 2. CAMBIO 7: marco formativo, sin promesa de ingresos. Marcar pagado=true, programar tarea a 48h. Transición a S11_POSTVENTA."},{"id":"S11_POSTVENTA","objetivo":"Retener, generar testimonios reales y sembrar futuras ofertas sin quemar el canal.","disparador":"48h después de la entrega (tarea programada).","mensajes":["[48H — DENTRO DE VENTANA] Hola {{nombre}} 😊 ¿Cómo vas con el curso? ¿Ya creaste tu primer modelo? Cuéntame, me encanta ver los avances 👀","[SI RESPONDE POSITIVO] ¡Qué nota! 🙌 ¿Me regalas una mini-reseña por aquí (texto o audio)? Con tu permiso la compartimos para que más personas se animen 💜","[SI RESPONDE CON PROBLEMA] Gracias por contarme 🙏 Vamos a resolverlo: dime exactamente en qué módulo o enlace tuviste el detalle y lo arreglo de una."],"notas":"CAMBIO 3: sin grupo/comunidad. Solo testimonios reales y con permiso se citan en ventas futuras."},{"id":"S90_FALLBACK_GPT","objetivo":"Responder CUALQUIER pregunta fuera de guion con el modelo GPT y devolver la conversación al riel del estado pendiente.","disparador":"Mensaje entrante que el clasificador de la etapa actual no reconoce.","mensajes":["[PLANTILLA DE COMPORTAMIENTO, NO COPY FIJO] GPT responde en máximo 3 líneas, tono Musa, usando SOLO el contexto del producto (qué es, qué incluye, precio 9 USD, métodos de pago, entrega por Drive, garantía de entrega) + lista negra de cumplimiento. Cierra SIEMPRE reconectando con la pregunta pendiente de la etapa actual."],"notas":"El system prompt del fallback vive en musa_settings clave gpt_system. Si la confianza es baja o el tema es delicado → S91_HUMANO."},{"id":"S91_HUMANO","objetivo":"Escalar a un humano del equipo sin romper la experiencia.","disparador":"Solicitud explícita de hablar con una persona, queja fuerte, fraude o baja confianza del fallback.","mensajes":["Dame un momentico, {{nombre}} 🙏 Voy a consultar esto con el equipo para darte una respuesta exacta. Te escribo en un ratico por aquí mismo."],"notas":"El bot pausa la automatización en ese chat hasta que el humano marque ''resuelto''."}],"objeciones":[{"objecion":"¿Es estafa? / no confío","respuesta":"Te entiendo perfecto, {{nombre}}, en internet hay que cuidarse 🙏 Por eso te dejo una muestra REAL de lo que hay adentro, para que la pruebes tú mismo gratis antes de pagar 👇\n\n🎨 *Retrato hiperrealista de una mujer joven latina, fotografía profesional, luz natural dorada, piel realista con textura, 85mm f/1.4* — pégalo en cualquier IA de imágenes y me cuentas qué tal 😏 Ese prompt es UNO de los del módulo de creación de modelos.\n\nAdemás la entrega es inmediata: pagas, verifico tu comprobante y recibes TODOS los enlaces por este mismo chat, así puedes comprobarlo todo al instante. ¿Qué otra duda te queda?"},{"objecion":"Está caro / no tengo plata","respuesta":"Tranquilo, te entiendo 🙏 Por eso el precio es el que es: 9 USD una sola vez ({{precio_bs}} Bs / {{precio_cop}} COP), menos de lo que cuesta una pizza 🍕, por 13 módulos + 4 bonos, con acceso de por vida. No hay mensualidades ni cobros escondidos. Si hoy no puedes, no pasa nada: dime cuándo te queda mejor y te guardo la info actualizada. ¿Te parece?"},{"objecion":"¿Me llega de inmediato?","respuesta":"¡Sí! 🚀 Apenas verifico tu comprobante (normalmente menos de 15 minutos en horario de 8am a 10pm), te entrego TODO por este mismo chat: los 13 módulos y los 4 bonos como enlaces directos de Google Drive. Nada de esperar correos ni plataformas raras."},{"objecion":"¿Sirve para principiantes?","respuesta":"Totalmente 💪 El curso arranca desde CERO: el módulo 1 te explica cómo funciona este mercado y de ahí vas paso a paso hasta crear tu primer modelo. No necesitas saber de diseño ni de programación, solo un celular o compu con internet. Está pensado para empezar sin experiencia."},{"objecion":"¿Funciona en mi país?","respuesta":"Sí 🌎 Todo el curso es online y las herramientas de IA que se enseñan funcionan desde cualquier país. La monetización también: las plataformas para vender contenido y atraer tráfico (TikTok, Instagram, etc.) están disponibles en Venezuela, Colombia y prácticamente toda LATAM. Para el pago tienes varios métodos y de eso me encargo yo 😉"},{"objecion":"¿Puedo pagar en bolívares / en pesos?","respuesta":"¡Claro que sí! 🙌 Son 9 USD: en Venezuela 🇻🇪 pagas {{precio_bs}} Bs (a la tasa de hoy) por Pago Móvil o transferencia Banco de Venezuela; en Colombia 🇨🇴 pagas {{precio_cop}} COP por Nequi, Bancolombia o llave Bre-B. Puedes usar el medio que más te sirva. ¿Te paso los datos?"},{"objecion":"¿Qué incluye exactamente?","respuesta":"Te lo resumo completico 👇 *13 módulos*: mercado de modelos IA, creación de tu modelo hiperrealista desde cero, contenido ilimitado, prompts avanzados de imagen y video, automatización de respuestas, monetización de packs y suscripciones, y tráfico desde TikTok e Instagram. *4 bonos*: Colección de +20 modelos IA premium, Audios FemPro, YouTube Money Machine y MegaPack Master IA. Y si decides hoy, el bono *Plan de Acción 7 Días*. Todo con acceso de por vida por un único pago de 9 USD."},{"objecion":"¿Es legal?","respuesta":"Sí 😊 Crear modelos virtuales con IA y vender contenido digital propio es una actividad legal: es contenido generado por ti, de personas que no existen, con herramientas públicas de IA. El curso además te enseña a trabajar dentro de las normas de cada plataforma. Lo que compras es formación: videos y guías paso a paso."},{"objecion":"Soy mujer, ¿me sirve?","respuesta":"¡Por supuesto! 💜 De hecho hay muchas mujeres en esto, y con ventaja: el negocio es crear y gestionar modelos VIRTUALES, tú nunca pones tu cara ni tu cuerpo, tú eres la dueña del negocio detrás. El método es exactamente el mismo: creas tu modelo con IA, generas el contenido y monetizas."},{"objecion":"¿Hay garantía?","respuesta":"Te garantizo la entrega completa: pagas y recibes los 13 módulos + 4 bonos verificables al instante, por este mismo chat 📲 Y no te vendo humo: esto es formación, los resultados dependen de que apliques lo que aprendes, como en cualquier curso. Lo que sí te aseguro es que recibes exactamente todo lo que te describí, con acceso de por vida, y me tienes aquí para cualquier problema con tu acceso."},{"objecion":"¿Por qué tan barato?","respuesta":"Buena pregunta 😄 El precio es así de accesible a propósito: queremos que cualquiera en Venezuela o Colombia pueda pagarlo, porque el negocio crece con muchos alumnos activos, no exprimiendo a cada uno. 9 USD, una vez, todo incluido. Sin letra pequeña."},{"objecion":"Déjame pensarlo","respuesta":"¡Claro, {{nombre}}, tómate tu tiempo! 😊 Solo dos cositas para que las tengas en cuenta: el monto en bolívares se ajusta con la tasa del día, así que hoy queda en {{precio_bs}} Bs; y a quienes confirman su pago dentro de las primeras 24 horas de su primer contacto les incluimos el *Plan de Acción 7 Días* de regalo (una guía extra que solo damos por decisión rápida, de verdad). Cualquier duda que te esté frenando, dímela con confianza, para eso estoy 💜"},{"objecion":"¿Eres un bot?","respuesta":"Sí 😄 Soy Musa, la asistente virtual del equipo de Modelos IA. Y te cuento un secreto: automatizar la atención así, con IA, es UNA de las cosas que enseña el curso (módulo de automatización 😉). Detrás hay un equipo humano real que verifica cada pago y te apoya si algo se complica. ¿Seguimos? ¿Qué más quieres saber?"}],"seguimientos":[{"retraso":"30 minutos sin respuesta (post-precio o post-cierre)","mensaje":"{{nombre}}, ¿quedaste con alguna duda? 😊 Pregúntame con confianza, para eso estoy. Te lo resumo en una línea: curso completo (13 módulos) + 4 bonos, pago único de 9 USD ({{precio_bs}} Bs / {{precio_cop}} COP), entrega inmediata por este chat. ¿Te paso los datos de pago?"},{"retraso":"4 horas sin respuesta","mensaje":"Hola {{nombre}} 👋 Te dejo una muestra REAL de lo que hay dentro del curso para que lo veas con tus propios ojos 👇\n\n🎨 *Retrato hiperrealista de una mujer joven latina, fotografía profesional, luz natural dorada, piel realista con textura, 85mm f/1.4*\n\nEse es solo UNO de los prompts del módulo de creación de modelos. Pruébalo gratis en cualquier IA de imágenes y me cuentas qué tal 😏 Imagínate con los 13 módulos completos. ¿Retomamos?"},{"retraso":"20 horas sin respuesta (última ventana antes de las 24h)","mensaje":"{{nombre}}, paso a contarte dos cosas reales antes de cerrar tu chat de hoy 😊\n\n1️⃣ La tasa del bolívar cambia cada día: hoy tu acceso queda en *{{precio_bs}} Bs* (o *{{precio_cop}} COP*); mañana el monto en Bs se recalcula.\n2️⃣ A quienes confirman su pago dentro de las primeras 24 horas les incluimos de regalo el *Plan de Acción 7 Días* 🎁: una guía extra con el paso a paso exacto de tu primera semana. Es real y solo se entrega por decisión rápida (tu plazo vence hoy a las {{hora_limite}}).\n\nSi te animas, te paso los datos en 10 segundos. Y si no es tu momento, todo bien, aquí quedo 💜"}],"template_post_24h":{"nombre_sugerido":"reactivacion_info_pendiente","categoria":"MARKETING","idioma":"es","cuerpo":"Hola {{1}} 👋 Soy Musa, del equipo de Modelos IA. Hace poco me pediste información sobre nuestro curso para crear y monetizar modelos virtuales con inteligencia artificial, y quedó pendiente completar tu acceso. Si todavía te interesa, responde SÍ y te envío la información actualizada con el precio en tu moneda local a la tasa del día. Si prefieres no recibir más mensajes, responde STOP y no te volvemos a escribir.","botones":["SÍ, quiero la info","STOP"],"notas":"Aprobación Meta: sin promesas de ingresos, sin urgencia artificial, sin contenido para adultos, con opt-out explícito. Enviar máximo 1 vez por lead frío. Respetar STOP de forma permanente."},"post_venta":["CONFIRMACIÓN: mensaje inmediato ''✅ ¡Pago confirmado! Bienvenido oficialmente a Modelos IA, {{nombre}} 🎉'' + registro de venta (monto, método, timestamp) y marca pagado=true.","ENTREGA ORDENADA DE LOS 17 ENLACES (anti-spam): agrupar en exactamente 2 mensajes de contenido: (1) BLOQUE 1 ''Curso completo — 13 módulos'' con los 13 enlaces numerados en UNA sola lista; (2) BLOQUE 2 ''Tus 4 bonos'' con los 4 enlaces (verificar flag mayor_18 antes de enviar; recordatorio de uso personal del material 🔞 sin describirlo). Nunca 17 mensajes separados. CAMBIO 3: NO hay bloque de comunidad/grupo.","PRIMER PASO CONCRETO (CAMBIO 7, marco formativo SIN promesa de ingresos): cerrar la entrega con dirección (''con dedicación y aplicando el paso a paso, empieza HOY por el Módulo 1, ~20 minutos, y en poco tiempo verás tu primer modelo creado y publicado''). PROHIBIDO prometer ganancias/ingresos garantizados.","TESTIMONIO A LAS 48H: tarea programada. Si la ventana de 24h sigue abierta, mensaje de sesión ''¿Cómo vas con el curso? ¿Ya creaste tu primer modelo?''; si responde positivo, pedir mini-reseña en texto o audio CON permiso explícito. Solo testimonios reales y con permiso se citan en ventas futuras.","SOPORTE POST-VENTA: cualquier reporte de enlace caído o acceso fallido tiene prioridad máxima → escalar a humano si el bot no resuelve en 1 intercambio.","SEMILLA DE FUTURAS OFERTAS: (1) en la entrega, pedir opt-in explícito ''¿Quieres que te avise cuando saquemos material nuevo o mejoras del curso? Responde SÍ y quedas en la lista VIP''; (2) tag #comprador + fecha como base segmentada. CAMBIO 3: sin grupo/comunidad."]}'::jsonb)
